{
  "name": "Wasatch USB光谱仪",
  "name_en": "Wasatch USB Spectrometer",
  "manufacturer": "Wasatch Photonics",
  "description": "通过 FID 协议控制 Wasatch Photonics USB 2.0 光谱仪的设备接口，用于采集光谱数据，并支持扫描平均、Auto-Raman、区域扫描、激光相关测量以及温度与状态信息读取，适用于拉曼和通用光谱实验。",
  "description_en": "A device interface for controlling Wasatch Photonics USB 2.0 spectrometers over the FID protocol. It is used for spectral acquisition and supports scan averaging, Auto-Raman, area scanning, laser-related measurements, and temperature/status readback for Raman and general spectroscopy workflows.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接指定的 Wasatch 光谱仪。",
      "description_en": "Connect to the specified Wasatch spectrometer."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与光谱仪的连接。",
      "description_en": "Disconnect from the spectrometer."
    },
    {
      "action_name": "auto-connect_feature_identification",
      "description": "使用 FID 协议连接兼容的光谱仪设备。",
      "description_en": "Connect to a compatible spectrometer using the FID protocol."
    },
    {
      "action_name": "auto-initialize_settings",
      "description": "初始化光谱仪设置与采集相关状态。",
      "description_en": "Initialize spectrometer settings and acquisition-related state."
    },
    {
      "action_name": "auto-acquire_data",
      "description": "处理待执行命令并从设备采集光谱与温度等数据。",
      "description_en": "Process pending commands and acquire spectrum and temperature-related data from the device."
    },
    {
      "action_name": "auto-acquire_spectrum",
      "description": "执行一次光谱采集，返回单次或平均后的读数及相关状态。",
      "description_en": "Perform a spectrum acquisition and return a single or averaged reading with related status."
    },
    {
      "action_name": "auto-acquire_spectrum_auto_raman",
      "description": "执行 Auto-Raman 光谱采集流程。",
      "description_en": "Run an Auto-Raman spectrum acquisition sequence."
    },
    {
      "action_name": "auto-acquire_spectrum_standard",
      "description": "执行标准光谱采集，可结合激光控制、平均和附加元数据读取。",
      "description_en": "Perform a standard spectrum acquisition, optionally with laser control, averaging, and additional metadata readout."
    },
    {
      "action_name": "auto-perform_optional_throwaways",
      "description": "执行可选的预热丢弃采集，以提高传感器或激光稳定性。",
      "description_en": "Perform optional throwaway acquisitions to improve sensor or laser stabilization."
    },
    {
      "action_name": "auto-take_one_averaged_reading",
      "description": "采集一次读数，必要时执行多次积分并在本地完成平均。",
      "description_en": "Acquire one reading, optionally performing multiple integrations and local averaging."
    },
    {
      "action_name": "auto-monitor_memory",
      "description": "监控采集过程中的内存使用情况。",
      "description_en": "Monitor memory usage during acquisition."
    },
    {
      "action_name": "auto-process_commands",
      "description": "处理队列中的设置命令并将其写入设备。",
      "description_en": "Process queued setting commands and write them to the device."
    },
    {
      "action_name": "auto-acquire_area_scan",
      "description": "执行区域扫描采集，返回区域扫描图像及相关光谱数据。",
      "description_en": "Perform an area scan acquisition and return area-scan image data with related spectral data."
    },
    {
      "action_name": "auto-balance_acquisition",
      "description": "调整采集参数以使目标像素或强度达到设定范围。",
      "description_en": "Adjust acquisition parameters to bring a target pixel or intensity into the desired range."
    },
    {
      "action_name": "auto-change_setting",
      "description": "更改设备或采集设置，必要时立即下发到硬件。",
      "description_en": "Change a device or acquisition setting, sending it to hardware immediately when needed."
    },
    {
      "action_name": "auto-handle_requests",
      "description": "处理上层发送的请求集合并分发到相应设备操作。",
      "description_en": "Handle batches of incoming requests and dispatch them to the appropriate device operations."
    }
  ],
  "tag_hints": [
    "USB spectrometer",
    "Raman spectroscopy",
    "spectral acquisition",
    "scan averaging",
    "laser control",
    "area scan",
    "temperature monitoring",
    "FID protocol"
  ]
}

